@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-accordion {
    display: flex;
    flex-direction: column;
  }

  .nz-accordion-item {
    border-block-end: var(--nz-border-width-default) solid
      var(--nz-accordion-border, var(--nz-border-subtle));
  }

  .nz-accordion-trigger {
    display: flex;
    align-items: center;
    gap: var(--nz-space-3);
    padding-block: var(--nz-space-4);
    padding-inline: var(--nz-accordion-padding-inline, var(--nz-space-0));
    border-radius: var(--nz-radius-sm);
    color: var(--nz-accordion-trigger-fg, var(--nz-text-primary));
    font: var(--nz-font-label-m-strong);
    letter-spacing: var(--nz-tracking-label-m);
    list-style: none;
    cursor: pointer;

    /* the browser's own disclosure triangle; the chevron replaces it */
    &::-webkit-details-marker {
      display: none;
    }
  }

  .nz-accordion-title {
    flex: 1;
    min-inline-size: 0;
  }

  .nz-accordion-indicator {
    display: inline-flex;
    flex: none;
    color: var(--nz-icon-secondary);
    font-size: var(--nz-size-icon-sm);
    rotate: 90deg;
    transition: rotate var(--nz-duration-fast) var(--nz-easing-standard);

    .nz-accordion-item[open] > .nz-accordion-trigger > & {
      rotate: -90deg;
    }
  }

  .nz-accordion-panel {
    padding-block: 0 var(--nz-space-4);
    padding-inline: var(--nz-accordion-padding-inline, var(--nz-space-0));
    color: var(--nz-text-secondary);
    font: var(--nz-font-body-m);
  }

  @media (forced-colors: active) {
    .nz-accordion-item {
      border-color: CanvasText;
    }

    .nz-accordion-indicator {
      color: CanvasText;
    }
  }

  /* Optical centring (M85, as Button's label): trimmed to cap height and baseline, padded back to
     one line, so the box keeps its height and the letters sit in its middle. */
  @supports (text-box: trim-both cap alphabetic) {
    .nz-accordion-title {
      padding-block: calc((1lh - 1cap) / 2);
      text-box: trim-both cap alphabetic;
    }
  }
}
